def backfill_money(apps, schema_editor):
    """Existing orders had only a total: the items were the whole price and nothing else was charged.

    Online orders that were paid hold their full total as money received; the payments migration
    adds their ledger rows.
    """
    Order = apps.get_model("orders", "Order")
    Order.objects.update(subtotal=models.F("total"), charges_total=0)
    Order.objects.filter(payment_method="online", payment_status="paid").update(amount_paid=models.F("total"))
